	#[test]
	fn stale_and_future_versions_are_distinguishable() {
		let error = PoolConfig::try_from_bytes(&envelope(1 as u8))
			.err()
			.expect("a future envelope must fail");
		assert_eq!(error, PoolConfigVersionError::Future { stored: 1 });
		assert_eq!(
			PoolConfigVersionError::Future { stored: 1 }.to_string(),
			"migration version mismatch: expected 0, received 1 (the data was written by a newer \
			 program; upgrade this client)"
		);
		assert!(
			PoolConfig::try_from_bytes(&envelope(0 as u8)).is_ok(),
			"the current version must decode",
		);
	}
